A.ae5=new B.aj("terbutaline","Terbutaline",A.b43,"\u0e40\u0e17\u0e2d\u0e23\u0e4c\u0e1a\u0e39\u0e17\u0e32\u0e25\u0e35\u0e19",A.l0,A.b4P,null,A.Y,A.V,null,!1,!1,!1,null,"C",A.bfZ,"Used off-label as a tocolytic (to stop preterm labor). Not for prolonged use > 48h.","\u0e23\u0e30\u0e27\u0e31\u0e07\u0e43\u0e08\u0e2a\u0e31\u0e48\u0e19 \u0e2b\u0e31\u0e27\u0e43\u0e08\u0e40\u0e15\u0e49\u0e19\u0e40\u0e23\u0e47\u0e27 (Tachycardia)","","",null,null,null,A.X)
